func (this *Tree) GetFocusItem() *TreeItem {
	var path []int64 = make([]int64, 1)
	gtk.GTKGtk_tree_view_get_cursor(this.Handle, path, nil)
	if path[0] == 0 {
		return nil
	}
	var item *TreeItem = nil
	var iter int64 = gtk.OSG_malloc(int64(gtk.GTKGtkTreeIter_sizeof()))
	if gtk.GTKGtk_tree_model_get_iter(this.modelHandle, iter, path[0]) {
		var index []int32 = make([]int32, 1)
		gtk.GTKGtk_tree_model_getTree_modelIterColumnValueTerminator(this.modelHandle, iter, TreeID_COLUMN, index, -1)
		if index[0] != -1 {
			item = this.items[index[0]]
		}
	}
	gtk.OSG_free(iter)
	gtk.GTKGtk_tree_path_free(path[0])
	return item
}

