func (this *Tree) GetHeaderHeight() int32 {
	this.CheckWidget()
	if !gtk.GTKGtk_tree_view_get_headers_visible(this.Handle) {
		return 0
	}
	var height int32 = 0
	if this.columnCount > 0 {
		var requisition gtk.GtkRequisition = gtk.GtkRequisition{}
		for i := int32(0); i < this.columnCount; i++ {
			var buttonHandle int64 = this.columns[i].buttonHandle
			if buttonHandle != 0 {
				this.impl.gtk_widget_get_preferred_size_(buttonHandle, &requisition)
				height = int32(math.Max(float64(height), float64(requisition.Height)))
			}
		}
	} else {
		if gtk.GTKGTK4 {
			var headerHeight []int32 = make([]int32, 1)
			gtk.GTKGtk_tree_view_convert_bin_window_to_widget_coords(this.Handle, 0, 0, nil, headerHeight)
			height = headerHeight[0]
		} else {
			gtk.GTKGtk_widget_realize(this.Handle)
			var fixedWindow int64 = this.Gtk_widget_get_window(this.fixedHandle)
			var binWindow int64 = gtk.GTK3Gtk_tree_view_get_bin_window(this.Handle)
			var binY []int32 = make([]int32, 1)
			gtk.GDKGdk_window_get_origin(binWindow, nil, binY)
			var fixedY []int32 = make([]int32, 1)
			gtk.GDKGdk_window_get_origin(fixedWindow, nil, fixedY)
			height = binY[0] - fixedY[0]
		}
	}
	return height
}

